CREATE TABLE [dbo].[ccoDialers](	  [dialer_id] INT NOT NULL IDENTITY(1,1)	, [Descripcion] VARCHAR(15) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [Puerto] INT NOT NULL	, [Extension] SMALLINT NOT NULL DEFAULT(0)	, [Status] TINYINT NOT NULL DEFAULT(0)	, [provedor_id] SMALLINT NULL DEFAULT(1)	, [XferType] TINYINT NOT NULL DEFAULT((3))	, CONSTRAINT [PK_ccodialers] PRIMARY KEY ([dialer_id] ASC))ALTER TABLE [dbo].[ccoDialers] WITH CHECK ADD CONSTRAINT [FK_ccoDialers_cstoProvedor] FOREIGN KEY([provedor_id]) REFERENCES [dbo].[cstoProvedor] ([provedor_id])ALTER TABLE [dbo].[ccoDialers] CHECK CONSTRAINT [FK_ccoDialers_cstoProvedor]CREATE NONCLUSTERED INDEX [IX_ccoDialers] ON [dbo].[ccoDialers] ([Puerto] ASC)CREATE NONCLUSTERED INDEX [IX_ccoDialers_I] ON [dbo].[ccoDialers] ([dialer_id] ASC, [provedor_id] ASC)INCLUDE ([Puerto], [Descripcion])